// Independent GNU Radio/gr-satellites vectors, not generated by this decoder.
#include "beacon_dsp.hpp"
#include <cstring>
#include <fstream>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <vector>
void require(bool ok,const char* text) {if(!ok)throw std::runtime_error(text);}
std::vector<uint8_t> read(const std::string& path) {
    std::ifstream in(path,std::ios::binary);require(bool(in),"Cannot open FEC test vector");
    return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};
}
int main(int argc,char** argv) {
    try {
        require(argc==2,"Expected vector directory");const std::string dir=argv[1];
        const auto raw=read(dir+"/ao40_frame.f32");require(raw.size()==5200*4,"Invalid golden frame length");
        std::vector<uint8_t> frame(5200),conv(5132);
        for(size_t i=0;i<frame.size();++i) {
            uint32_t bits=uint32_t(raw[4*i])|(uint32_t(raw[4*i+1])<<8)|(uint32_t(raw[4*i+2])<<16)|(uint32_t(raw[4*i+3])<<24);
            float value;std::memcpy(&value,&bits,4);frame[i]=value>0;
        }
        for(size_t j=65;j<5197;++j)conv[j-65]=frame[80*(j%65)+j/65];
        const auto decoded=qo100::beacon::viterbi(conv);
        require(decoded==read(dir+"/post_viterbi.bin"),"C++ Viterbi differs from independent golden vector");
        const auto expected=read(dir+"/payload.bin");
        const auto bytes=qo100::beacon::descramble(decoded);
        std::vector<uint8_t> payload;int errors=-1;
        require(qo100::beacon::fec_frame(frame,payload,errors) && errors==0 && payload==expected,"C++ AO-40 FEC payload differs");
        for(unsigned damaged:{1u,8u,16u}) {
            auto corrupted=bytes;
            for(unsigned word=0;word<2;++word)for(unsigned n=0;n<damaged;++n)corrupted[2*(n*9)+word]^=uint8_t(37+n);
            require(qo100::beacon::rs_frame(corrupted,payload,errors) && errors==int(2*damaged) && payload==expected,"RS error correction differs");
        }
        require(qo100::beacon::descramble(std::vector<uint8_t>(8))==std::vector<uint8_t>({255,72,14,192,154,13,112,188}),"CCSDS sequence differs");
        std::vector<uint8_t> message(512,0);const auto crc=qo100::beacon::crc16(message);message.push_back(crc>>8);message.push_back(crc&255);
        require(qo100::beacon::crc16(message)==0,"CYC2 CRC validation failed");message[20]^=1;
        require(qo100::beacon::crc16(message)!=0,"Corrupt payload passed CRC");
        std::cout<<"C++ AO-40: golden Viterbi/payload, two RS words with 0/1/8/16 errors, CCSDS and CRC passed\n";
    } catch(const std::exception& e) {std::cerr<<e.what()<<'\n';return 1;}
}
